INSERT INTO [Attractions] (Id, Name, [Description], LocationId, OpeningTime, ClosingTime, EntranceFee, Latitude, Longitude, CreatedAt, UpdatedAt) VALUES
(1, N'น้ำตกเอราวัณ', N'น้ำตก 7 ชั้นสีเขียวมรกตในอุทยานแห่งชาติเอราวัณ เป็นน้ำตกที่สวยที่สุดแห่งหนึ่งของประเทศไทย แต่ละชั้นมีสระน้ำใสเย็นให้เล่นน้ำ สามารถเดินป่าขึ้นไปถึงชั้น 7 ใช้เวลาประมาณ 2 ชั่วโมง', 1, '08:00', '16:30', 300, 14.3752, 99.1444, GETUTCDATE(), GETUTCDATE()),
(2, N'สะพานข้ามแม่น้ำแคว', N'สะพานประวัติศาสตร์สมัยสงครามโลกครั้งที่ 2 สร้างโดยเชลยศึกฝ่ายสัมพันธมิตรภายใต้การควบคุมของกองทัพจักรวรรดิญี่ปุ่น เป็นส่วนหนึ่งของทางรถไฟสายมรณะ ปัจจุบันยังคงใช้งานได้จริง', 2, '06:00', '18:00', 0, 14.0416, 99.5042, GETUTCDATE(), GETUTCDATE()),
(3, N'น้ำตกไทรโยคน้อย', N'น้ำตกหินปูนสวยงาม ตั้งอยู่ในอุทยานแห่งชาติไทรโยค มีถ้ำและทางเดินป่าที่น่าสนใจ น้ำตกไหลจากผาหินปูนสูง บรรยากาศร่มรื่น เหมาะแก่การพักผ่อน', 3, '08:00', '16:00', 200, 14.7405, 98.8441, GETUTCDATE(), GETUTCDATE()),
(4, N'เขื่อนศรีนครินทร์', N'เขื่อนอเนกประสงค์กั้นแม่น้ำแควใหญ่ เป็นเขื่อนหินถมดินบดอัดแน่นที่ใหญ่ที่สุดในประเทศไทย ทัศนียภาพงดงาม มีกิจกรรมล่องแพ ตกปลา และชมวิวเหนือเขื่อน', 4, '06:00', '18:00', 0, 14.0898, 99.0044, GETUTCDATE(), GETUTCDATE()),
(5, N'วัดถ้ำเสือ', N'วัดที่มีพระพุทธรูปองค์ใหญ่ตั้งอยู่บนยอดเขา ต้องเดินขึ้นบันได 237 ขั้น จากด้านบนสามารถมองเห็นทิวทัศน์เมืองกาญจนบุรีได้ 360 องศา เป็นจุดชมวิวที่สวยที่สุดแห่งหนึ่ง', 5, '08:00', '16:30', 0, 14.0500, 99.5350, GETUTCDATE(), GETUTCDATE()),
(6, N'สุสานสงคราม (ดอนรัก)', N'สุสานทหารสัมพันธมิตรที่เสียชีวิตระหว่างก่อสร้างทางรถไฟสายมรณะ ดูแลโดย Commonwealth War Graves Commission มีหลุมศพเรียงรายอย่างเป็นระเบียบ สถานที่เงียบสงบเหมาะแก่การรำลึก', 6, '08:00', '16:00', 0, 14.0384, 99.5316, GETUTCDATE(), GETUTCDATE()),
(7, N'ถ้ำกระแซ', N'ถ้ำหินปูนขนาดใหญ่ที่มีหินงอกหินย้อยสวยงาม ตั้งอยู่ใกล้กับทางรถไฟสายมรณะ สามารถนั่งรถไฟผ่านสะพานถ้ำกระแซที่ตัดผ่านหน้าผาชันเหนือแม่น้ำแควน้อย เป็นเส้นทางรถไฟที่สวยที่สุดในไทย', 7, '08:00', '17:00', 0, 14.1021, 99.4150, GETUTCDATE(), GETUTCDATE()),
(8, N'น้ำตกไทรโยคใหญ่', N'น้ำตกขนาดใหญ่ในอุทยานแห่งชาติไทรโยค ตั้งอยู่ริมแม่น้ำแควน้อย มีความสูงประมาณ 20 เมตร น้ำตกจะสวยที่สุดในช่วงฤดูฝน บริเวณโดยรอบเป็นป่าดิบชื้น เหมาะแก่การเดินป่าและดูนก', 8, '08:00', '16:00', 200, 14.8190, 98.7700, GETUTCDATE(), GETUTCDATE());
INSERT INTO [Accommodations] (Id, Name, [Description], AccommodationType, LocationId, PricePerNight, MaxGuests, Latitude, Longitude, CreatedAt) VALUES
(1, N'เดอะ โฟลทเฮ้าส์ ริเวอร์แคว', N'ที่พักแพลอยน้ำริมแม่น้ำแคว บรรยากาศสุดโรแมนติก ตื่นมาเปิดประตูเจอแม่น้ำ มีกิจกรรมพายเรือคายัค ห้องพักตกแต่งสไตล์ไม้อบอุ่น อาหารเช้าเสิร์ฟบนแพ', 1, 9, 2500, 4, 14.0430, 99.5060, GETUTCDATE()),
(2, N'ริเวอร์แคว วิลเลจ', N'รีสอร์ทหรูระดับ 4 ดาวริมแม่น้ำแคว สไตล์หมู่บ้านชนบทไทย ล้อมรอบด้วยธรรมชาติ มีสระว่ายน้ำ สปา และร้านอาหารวิวแม่น้ำ', 1, 10, 3500, 2, 14.0350, 99.5200, GETUTCDATE()),
(3, N'ไอยรา รีสอร์ท แอนด์ สปา', N'รีสอร์ทหรูริมแม่น้ำแคว มีห้องพักแบบวิลล่าส่วนตัว สระว่ายน้ำอินฟินิตี้ สปาและร้านอาหารชั้นเลิศ เหมาะสำหรับฮันนีมูนและพักผ่อนระดับพรีเมียม', 1, 11, 5800, 2, 14.0470, 99.5080, GETUTCDATE()),
(4, N'โฟลทติ้ง รีสอร์ท ไทรโยค', N'แพลอยน้ำท่ามกลางธรรมชาติที่อำเภอไทรโยค ห้องพักแบบแพไม้ไผ่ดั้งเดิมแต่สะอาดสะอ้าน กิจกรรมล่องแพ เดินป่า และชมน้ำตก อาหารอร่อยจากวัตถุดิบท้องถิ่น', 1, 12, 1800, 6, 14.7500, 98.8300, GETUTCDATE()),
(5, N'X2 รีสอร์ท ริเวอร์แคว', N'รีสอร์ทดีไซน์ทันสมัยริมแม่น้ำแคว ห้องพักตกแต่งสไตล์มินิมอล มีสระว่ายน้ำส่วนตัว ร้านอาหารและบาร์วิวแม่น้ำ สถาปัตยกรรมเก๋ๆ เหมาะกับคู่รักและครอบครัว', 1, 13, 4200, 3, 14.1055, 99.4100, GETUTCDATE()),
(6, N'แคมป์ปิ้ง เอราวัณ ริเวอร์ แคมป์', N'แคมป์ปิ้งใกล้น้ำตกเอราวัณ มีเต็นท์หรูพร้อมเตียงนอนสบาย ห้องน้ำสะอาด กิจกรรมล่องแก่ง เดินป่า และนอนนับดาว อาหารค่ำบาร์บีคิวท่ามกลางธรรมชาติ', 4, 14, 1200, 4, 14.3800, 99.1500, GETUTCDATE());
INSERT INTO [Restaurants] (Id, Name, [Description], FoodType, LocationId, OpeningTime, ClosingTime, Latitude, Longitude, CreatedAt) VALUES
(1, N'บ้านริมน้ำ', N'ร้านอาหารไทยชื่อดังริมแม่น้ำแคว บรรยากาศดี วิวสะพานข้ามแม่น้ำแคว เมนูเด็ดคือปลาแม่น้ำ ต้มยำกุ้งแม่น้ำ และผัดไทยกุ้งสด เปิดมานานกว่า 30 ปี', 0, 15, '10:00', '22:00', 14.0490, 99.5100, GETUTCDATE()),
(2, N'ครัวอารีย์ราย', N'ร้านอาหารไทยท้องถิ่นในตัวเมืองกาญจนบุรี อาหารรสชาติจัดจ้าน เมนูเด็ดคือแกงส้มชะอม ต้มยำปลา และส้มตำ ราคาประหยัด บรรยากาศเป็นกันเอง', 0, 16, '09:00', '21:00', 14.0360, 99.5180, GETUTCDATE()),
(3, N'ก๋วยเตี๋ยวเรือป้าแดง', N'ร้านก๋วยเตี๋ยวเรือชื่อดังของกาญจนบุรี น้ำซุปเข้มข้น เนื้อเปื่อย ลูกชิ้นเด้ง ราคาชามละ 15-20 บาท คิวยาวทุกวัน เปิดมากว่า 20 ปี เป็นร้านที่ต้องลองเมื่อมากาญจนบุรี', 4, 16, '07:00', '15:00', 14.0365, 99.5185, GETUTCDATE()),
(4, N'Blue Rice by Keeree Mantra', N'ร้านอาหารวิวหลักล้าน ตั้งอยู่บนเขา มองเห็นแม่น้ำแควและทิวทัศน์เมืองกาญจนบุรี เสิร์ฟอาหารไทยฟิวชั่นและอาหารนานาชาติ บรรยากาศโรแมนติก เหมาะกับดินเนอร์', 5, 5, '11:00', '22:00', 14.0500, 99.5350, GETUTCDATE()),
(5, N'แพอาหาร ริมแคว', N'ร้านอาหารบนแพลอยน้ำแม่น้ำแคว อาหารทะเลสดๆ และอาหารไทยพื้นบ้าน เมนูแนะนำคือปลาเผาเกลือ กุ้งแม่น้ำเผา และยำสมุนไพร นั่งกินอาหารพร้อมชมพระอาทิตย์ตก', 1, 17, '10:00', '21:00', 14.0445, 99.5070, GETUTCDATE()),
(6, N'Meena Cafe', N'คาเฟ่สุดชิคริมแม่น้ำแคว ตกแต่งสไตล์อินดัสเทรียลผสมธรรมชาติ กาแฟดริปจากเมล็ดท้องถิ่น เค้กโฮมเมดอร่อย วิวแม่น้ำสุดปัง เหมาะกับการนั่งชิลยามบ่าย', 2, 18, '08:00', '18:00', 14.0425, 99.5055, GETUTCDATE());
